root.command:

IF OBJECT_ID(N'dbo.PeopleTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.PeopleTbl', N'HandsOverCollections') IS NOT NULL
   AND COL_LENGTH(N'dbo.PeopleTbl', N'DeliveryType') IS NOT NULL
   AND NOT EXISTS (
       SELECT 1
       FROM sys.extended_properties ep
       WHERE ep.major_id = OBJECT_ID(N'dbo.PeopleTbl')
         AND ep.minor_id = 0
         AND ep.name = N'HandsOverCollectionsSeeded_v1')
BEGIN
    EXEC (N'UPDATE dbo.PeopleTbl SET HandsOverCollections = 1
            WHERE Enabled = 1 AND (DeliveryType = ''DELIVER'' OR Person LIKE N''Sisanda%'')');

    EXEC sys.sp_addextendedproperty
        @name = N'HandsOverCollectionsSeeded_v1',
        @value = N'1',
        @level0type = N'SCHEMA', @level0name = N'dbo',
        @level1type = N'TABLE',  @level1name = N'PeopleTbl';
END
